action.mutation:
mutation CreateTransactionType($payload: [TransactionTypeCreatePayloadInput!]!) {
  mutation: createTransactionType(payload: $payload) { 
    id
    name
  }
}

mutation UpdateTransactionType($payload: [TransactionTypeUpdatePayloadInput!]!) {
  mutation: updateTransactionType(payload: $payload) { 
    id
    name
  }
}

mutation DeleteTransactionType($payload: [TransactionTypeDeletePayloadInput!]!) {
  mutation: deleteTransactionType(payload: $payload) { 
    id
    name
  }
}
